# Print keys at top level
print(type(data))
if isinstance(data, dict):
    print('Keys:', list(data.keys())[:10])
    # Look for any nested dict with payroll
    def search(obj, target='payroll'):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if target.lower() in k.lower():
                    print(f'Found key: {k}')
                search(v, target)
        elif isinstance(obj, list):
            for item in obj[:10]:
                search(item, target)
    search(data)
elif isinstance(data, list):
    print('Length:', len(data))
    print('First item type:', type(data[0]) if data else 'empty')
